package com.tekwatt.invoice.dto;import com.tekwatt.invoice.entity.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;public record InvoiceResponse(UUID id,UUID tenantId,UUID userId,UUID billId,String invoiceNumber,String customerName,String customerEmail,String billingAddress,String taxRegistrationNumber,BigDecimal subtotal,BigDecimal taxAmount,BigDecimal totalAmount,String currency,InvoiceStatus status,LocalDate issueDate,LocalDate dueDate,Instant issuedAt,Instant paidAt,Instant createdAt,Instant updatedAt){public static InvoiceResponse from(Invoice i){return new InvoiceResponse(i.getId(),i.getTenantId(),i.getUserId(),i.getBillId(),i.getInvoiceNumber(),i.getCustomerName(),i.getCustomerEmail(),i.getBillingAddress(),i.getTaxRegistrationNumber(),i.getSubtotal(),i.getTaxAmount(),i.getTotalAmount(),i.getCurrency(),i.getStatus(),i.getIssueDate(),i.getDueDate(),i.getIssuedAt(),i.getPaidAt(),i.getCreatedAt(),i.getUpdatedAt());}}
